<?php
require_once __DIR__.'/includes/bootstrap.php';
$category=(int)($_GET['category']??0);$service=(int)($_GET['service']??0);$city=trim($_GET['city']??'');$search=trim($_GET['q']??'');$page=max(1,(int)($_GET['page']??1));$limit=12;$offset=($page-1)*$limit;
$where=["p.status='published'"];$args=[];if($category){$where[]='p.category_id=?';$args[]=$category;}if($service){$where[]='EXISTS(SELECT 1 FROM project_services ps WHERE ps.project_id=p.id AND ps.service_id=?)';$args[]=$service;}if($city!==''){$where[]='p.city=?';$args[]=$city;}if($search!==''){$where[]='(p.title LIKE ? OR p.short_description LIKE ?)';$args[]="%$search%";$args[]="%$search%";}$condition=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM projects p WHERE $condition");$count->execute($args);$total=(int)$count->fetchColumn();$stmt=db()->prepare("SELECT p.*,CASE WHEN p.cover_image_public=1 AND p.cover_image_approved=1 THEN p.cover_image ELSE NULL END AS public_cover_image,c.name category_name,(SELECT COUNT(*) FROM page_views v WHERE v.project_id=p.id) views FROM projects p JOIN project_categories c ON c.id=p.category_id WHERE $condition ORDER BY p.is_featured DESC,p.display_order,p.created_at DESC LIMIT $limit OFFSET $offset");$stmt->execute($args);$projects=$stmt->fetchAll();$categories=db()->query('SELECT id,name FROM project_categories WHERE is_active=1 ORDER BY name')->fetchAll();$services=db()->query('SELECT id,name FROM services WHERE is_active=1 ORDER BY name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Our Projects | DreamBrixs</title><meta name="description" content="Explore DreamBrixs residential construction, architecture and interior projects."></head><body><header><h1>Our Projects</h1></header><form method="get"><input name="q" placeholder="Search projects" value="<?=e($search)?>"><select name="category"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="service"><option value="0">All services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$service===$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select><input name="city" placeholder="City" value="<?=e($city)?>"><button>Filter</button></form><main><p><?=count($projects)?> projects on this page · <?= $total?> total results</p><?php foreach($projects as $p):?><article><a href="/projects/<?=e($p['slug'])?>"><?php if($p['public_cover_image']):?><img src="<?=base_url('media.php?project='.$p['id'].'&type=cover')?>" alt="<?=e($p['title'])?>" width="280"><?php endif;?><h2><?=e($p['title'])?></h2></a><p><?=e($p['short_description'])?></p><p><?=e($p['category_name'])?> · <?=e($p['location']??$p['city']??'')?></p><p>Views: <?= (int)$p['views']?></p></article><?php endforeach;?></main><?php $pages=(int)ceil($total/$limit);for($i=1;$i<=$pages;$i++):?><a href="?<?=http_build_query(array_merge($_GET,['page'=>$i]))?>"><?=$i?></a> <?php endfor;?></body></html>
